-- Batch 1: N2 grammar meanings + enrichment, extracted from bunpo_N2.pdf pages 1-21
-- (pages 1-20 required; page 21 read only to complete item 34 ~ものだから whose
-- content spans pages 20-21). Covers 34 grammar points (TOC items 1-34).
-- All 34 titles matched exactly against supabase/n2_grammar_id_title.tsv - no unmatched items.

-- ============ grammar_meanings ============

-- 1. ~として（は）/~としても/~としての
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('1921b09f-1fbf-5365-93a8-19df0f52dc2a', 0, 'Nêu tư cách, vai trò, thân phận của người/vật khi thực hiện việc gì (với tư cách là...).', ARRAY['彼は国費留学生として日本へ来た。','彼は医者であるが、小説家としても有名である。']::text[], ARRAY['Anh ấy đã đến Nhật với tư cách là lưu học sinh học bổng nhà nước.','Ông ấy tuy là bác sĩ, nhưng cũng nổi tiếng với tư cách là một tiểu thuyết gia.']::text[]);

-- 2. ~とともに
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('b52c5fac-a86e-557a-9a97-6e18a027bc8d', 0, 'Cùng với, cùng ai/cái gì đó (đi kèm danh từ chỉ người/vật).', ARRAY['お正月は家族とともに過ごしたい。','大阪は東京とともに日本経済の中心地である。']::text[], ARRAY['Tôi muốn ăn Tết cùng gia đình.','Osaka cùng với Tokyo là các trung tâm kinh tế của Nhật Bản.']::text[]);
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('b52c5fac-a86e-557a-9a97-6e18a027bc8d', 1, 'Đồng thời với việc gì đó, vừa làm việc này vừa làm việc kia.', ARRAY['小林氏は、学生を指導するとともに、研究にも力を入れている。','この製品の開発は、困難であるとともに、費用がかかる。']::text[], ARRAY['Ông Kobayashi vừa hướng dẫn sinh viên, vừa dồn sức cho nghiên cứu.','Việc phát triển sản phẩm này vừa khó khăn, vừa tốn nhiều chi phí.']::text[]);
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('b52c5fac-a86e-557a-9a97-6e18a027bc8d', 2, 'Một sự thay đổi xảy ra thì kéo theo một sự thay đổi khác cũng xảy ra.', ARRAY['年をとるとともに、体力が衰える。','自動車が普及するとともに、交通事故も増えてきた。']::text[], ARRAY['Cùng với tuổi tác tăng lên, thể lực cũng suy giảm.','Cùng với việc ô tô trở nên phổ biến, tai nạn giao thông cũng tăng lên.']::text[]);

-- 3. ~において（は）/~においても/~における
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('9bb0d0f6-5878-51c2-a134-6e7efa2374b1', 0, 'Chỉ địa điểm hoặc thời gian diễn ra sự việc, mang sắc thái trang trọng hơn で thông thường.', ARRAY['会議は第一会議室において行われる。','それは私の人生における最良の日であった。']::text[], ARRAY['Hội nghị được tổ chức tại phòng họp số 1.','Đó là ngày đẹp nhất trong cuộc đời tôi.']::text[]);

-- 4. ~に応じて/~に応じ/~に応じた
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('983b21b1-3f11-5cdb-aaac-1449ab9892b2', 0, 'Tuỳ theo, phù hợp/cân xứng với tình huống hay điều kiện đã nêu.', ARRAY['保険金は被害状況に応じて、払われる。','無理をしないで体力に応じた運動をしてください。']::text[], ARRAY['Tiền bảo hiểm sẽ được chi trả tuỳ theo tình trạng thiệt hại.','Đừng gắng sức, hãy tập luyện phù hợp với thể lực của mình.']::text[]);

-- 5. ~にかわって/~にかわり
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('7a5bdce1-c437-59d1-9d9b-46ef8dc7916b', 0, 'Thay thế hoàn toàn cho cái cũ (cái cũ không còn dùng nữa, được thay bằng cái mới).', ARRAY['ここでは、人間にかわってロボットが作業をしている。','今はタイプライターにかわり、ワープロが使われている。']::text[], ARRAY['Ở đây, robot đang làm việc thay cho con người.','Bây giờ, thay cho máy đánh chữ, máy vi tính được sử dụng.']::text[]);
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('7a5bdce1-c437-59d1-9d9b-46ef8dc7916b', 1, 'Làm thay, đại diện cho một người khác (thường là người có vai vế cao hơn).', ARRAY['父にかわって、私が結婚式に出席しました。','首相にかわり、外相がアメリカを訪問した。']::text[], ARRAY['Tôi đã thay bố đi dự đám cưới.','Thay mặt thủ tướng, bộ trưởng ngoại giao đã đi thăm Mỹ.']::text[]);

-- 6. ~に比べて/~に比べ
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('960445c3-aa9b-57e2-9948-bb88b409af8f', 0, 'So với, lấy đối tượng nêu ra làm chuẩn để so sánh mức độ khác nhau.', ARRAY['兄に比べて、弟はよく勉強する。','今年は去年に比べ、雨の量が多い。']::text[], ARRAY['So với anh trai, em trai chăm học hơn.','Năm nay so với năm ngoái, lượng mưa nhiều hơn.']::text[]);

-- 7. ~にしたがって/~にしたがい
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('491bbfa2-cf02-582f-94d1-d9b80014d682', 0, 'Cùng với sự thay đổi của vế trước, vế sau cũng thay đổi theo (theo, tuỳ theo).', ARRAY['高く登るにしたがって、見晴らしがよくなった。','電気製品の普及にしたがって、家事労働が楽になった。']::text[], ARRAY['Khi lên cao, tầm nhìn cũng trở nên rõ hơn.','Theo sự phổ biến của đồ điện gia dụng, việc nhà cũng nhàn hơn.']::text[]);

-- 8. ~につれて/~につれ
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('2b817f7e-e626-547d-9bb6-4baae56d3dc5', 0, 'Cùng với sự thay đổi của vế trước, vế sau cũng thay đổi theo một cách tự nhiên, dần dần.', ARRAY['品質がよくなるにつれて、値段が高くなる。','年をとるにつれ、昔のことが懐かしく思い出される。']::text[], ARRAY['Khi chất lượng tốt lên, giá cả cũng cao hơn.','Càng lớn tuổi, người ta càng nhớ về những chuyện ngày xưa.']::text[]);

-- 9. ~に対して（は）/~に対し/~に対しても/~に対する
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('d77a1e12-f7d4-5ac2-8d62-de3e71d9312d', 0, 'Chỉ đối tượng, đối phương mà hành động/thái độ hướng tới.', ARRAY['お客様に対して失礼なことを言ってはいけません。','被害者に対する補償問題を検討する。']::text[], ARRAY['Không được nói điều thất lễ với khách hàng.','Chúng tôi xem xét vấn đề bồi thường cho nạn nhân.']::text[]);

-- 10. ~について（は）/~につき/~についても/~についての
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('2cf50cce-fb26-520c-a819-aed92216a848', 0, 'Nêu nội dung đang nói, suy nghĩ, nghiên cứu tới (về, liên quan đến).', ARRAY['日本の経済について研究しています。','コンピューターの使い方についての本がほしい。']::text[], ARRAY['Tôi đang nghiên cứu về kinh tế Nhật Bản.','Tôi muốn có một cuốn sách nói về cách sử dụng máy tính.']::text[]);

-- 11. ~にとって（は）/~にとっても/~にとっての
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('86cc8574-9590-5229-8ef0-1af4e4fc68a0', 0, 'Đứng từ góc độ/lập trường của ai đó để đưa ra nhận xét, đánh giá.', ARRAY['この写真は私にとって、何よりも大切なものです。','だれにとっても一番大切なのは健康です。']::text[], ARRAY['Bức ảnh này đối với tôi quan trọng hơn bất cứ thứ gì.','Đối với bất kỳ ai, sức khoẻ là điều quan trọng nhất.']::text[]);

-- 12. ~に伴って/~に伴い/~に伴う
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('7df4deaf-d5fc-5a27-8f02-26215b350a62', 0, 'Kèm theo, đi cùng với một sự thay đổi (gần nghĩa にしたがって/につれて).', ARRAY['人口が増えるに伴って、いろいろな問題が起こってきた。','経済発展にともなう環境破壊が問題になっている。']::text[], ARRAY['Đi kèm với việc dân số tăng, nhiều vấn đề đa dạng đã nảy sinh.','Việc phá hoại môi trường đi kèm với phát triển kinh tế đang trở thành vấn đề nan giải.']::text[]);
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('7df4deaf-d5fc-5a27-8f02-26215b350a62', 1, 'Hai sự việc xảy ra đồng thời, cùng lúc với nhau.', ARRAY['地震に伴って、火災が発生することが多い。','自由には、それに伴う責任がある。']::text[], ARRAY['Cùng với động đất, hoả hoạn cũng thường xảy ra.','Tự do luôn đi kèm với trách nhiệm tương ứng.']::text[]);

-- 13. ~によって/~により/~による/~によっては
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('721e6341-58cf-51ef-97ef-80504a084229', 0, 'Chỉ chủ thể thực hiện hành động, thường dùng trong câu bị động (do, bởi).', ARRAY['アメリカ大陸はコロンブスによって発見された。','この法案は国会により承認された。']::text[], ARRAY['Châu Mỹ được Columbus phát hiện ra.','Dự luật này đã được Quốc hội thông qua.']::text[]);
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('721e6341-58cf-51ef-97ef-80504a084229', 1, 'Chỉ nguyên nhân, lý do dẫn đến kết quả.', ARRAY['不注意によって大事故が起こることもある。','首相が暗殺されたことにより、A国の政治は混乱した。']::text[], ARRAY['Có những vụ tai nạn lớn xảy ra do sự bất cẩn.','Vì thủ tướng bị ám sát, chính trị nước A đã hỗn loạn.']::text[]);
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('721e6341-58cf-51ef-97ef-80504a084229', 2, 'Chỉ phương thức, biện pháp thực hiện việc gì.', ARRAY['問題は話し合いによって解決した方がいい。','先生はテストにより、学生が理解したかどうかをチェックする。']::text[], ARRAY['Vấn đề nên được giải quyết bằng cách đối thoại.','Giáo viên kiểm tra học sinh có hiểu bài hay không bằng bài kiểm tra.']::text[]);
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('721e6341-58cf-51ef-97ef-80504a084229', 3, 'Tuỳ theo đối tượng mà có sự khác nhau.', ARRAY['習慣は国によって違う。','服装の時代による変化について研究したい。']::text[], ARRAY['Tập quán khác nhau tuỳ theo từng nước.','Tôi muốn nghiên cứu về sự thay đổi của trang phục theo từng thời đại.']::text[]);
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('721e6341-58cf-51ef-97ef-80504a084229', 4, 'Có trường hợp/đối tượng nào đó thì... (dùng dạng によっては).', ARRAY['この薬は人によっては副作用が出ることがあります。','宗教によっては肉を食べることを禁じられている。']::text[], ARRAY['Loại thuốc này có thể gây tác dụng phụ với một số người.','Có tôn giáo mà việc ăn thịt bị cấm.']::text[]);

-- 14. ~によると/~によれば
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('8cfd8bee-b151-5705-a88a-1012faef7b87', 0, 'Căn cứ nguồn tin để nói lại (theo... thì nghe nói), thường đi với そうだ/ということだ ở cuối câu.', ARRAY['今朝の新聞によると、来年度、二つの大学が新設されるそうだ。','天気予報によると、あしたは雨が降るそうです。']::text[], ARRAY['Theo báo sáng nay, nghe nói sang năm sẽ có hai trường đại học mới được thành lập.','Theo dự báo thời tiết, nghe nói ngày mai trời sẽ mưa.']::text[]);

-- 15. ~を中心に（して）/~を中心として
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('5bdfa8a2-646b-5039-a65a-dd9f9a9853ee', 0, 'Lấy cái gì đó làm trung tâm, làm chủ đạo.', ARRAY['駅を中心にたくさんの商店が集まっている。','この国は自動車産業を中心に工業を進めている。']::text[], ARRAY['Nhiều cửa hàng tập trung quanh nhà ga.','Nước này phát triển công nghiệp lấy ngành sản xuất ô tô làm trung tâm.']::text[]);

-- 16. ~を問わず/~は問わず
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('76dd1cae-6d93-5532-b6ec-fb6962b5e348', 0, 'Không kể, bất kể, không phân biệt (yếu tố nêu ra không ảnh hưởng đến việc phía sau).', ARRAY['留学生ならどなたでも国籍、年齢、性別を問わず申し込めます。','この病院では昼夜を問わず救急患者を受け付けます。']::text[], ARRAY['Nếu là du học sinh, bất kỳ ai cũng có thể đăng ký, không kể quốc tịch, tuổi tác, giới tính.','Bệnh viện này tiếp nhận bệnh nhân cấp cứu không kể ngày đêm.']::text[]);

-- 17. ~をはじめ/~をはじめとする
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('1bf5b207-3099-59c4-bb34-0eb2c51a94f4', 0, 'Nêu một ví dụ điển hình, tiêu biểu nhất trong một nhóm (đứng đầu là..., bắt đầu từ...).', ARRAY['上野動物園にはパンダをはじめ、子供たちに人気がある動物がたくさんいます。','国会議員をはじめとする視察団が被災地を訪れた。']::text[], ARRAY['Ở vườn thú Ueno có rất nhiều động vật được trẻ em yêu thích, đứng đầu là gấu trúc.','Đoàn thị sát, đứng đầu là các nghị sĩ Quốc hội, đã đến thăm vùng bị thiên tai.']::text[]);

-- 18. ~をもとに/~を元にして
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('be4d2740-8b3b-5dcf-962d-868b11600255', 0, 'Lấy cái gì đó làm cơ sở, căn cứ, tài liệu để làm việc khác.', ARRAY['ファンの人気投票をもとに審査し、今年の歌のベストテンが決まります。','ノンフィクションというのは事実を元にして書かれたものです。']::text[], ARRAY['Bảng xếp hạng ca khúc top 10 năm nay được quyết định dựa trên kết quả bình chọn của người hâm mộ.','Thể loại phi hư cấu là loại được viết dựa trên sự thật.']::text[]);

-- 19. ~上（に）
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('04ad6c89-1aec-5959-bc3a-0f91f9ba351c', 0, 'Không chỉ... mà còn, thêm vào đó (bổ sung một điều tương tự hoặc nghiêm trọng hơn).', ARRAY['今年のインフルエンザは高熱が出る上、せきもひどい。','彼女は頭がいいうえに、性格もよい。']::text[], ARRAY['Cúm năm nay không chỉ gây sốt cao mà còn ho dữ dội.','Cô ấy không chỉ thông minh mà tính cách còn rất tốt.']::text[]);

-- 20. ~うちに/~ないうちに
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('0b4b8464-a058-5549-b080-6159eb9c051c', 0, 'Trong lúc, tranh thủ làm gì đó trước khi trạng thái hiện tại thay đổi.', ARRAY['日本にいるうちに、一度京都を訪ねたいと思っている。','花がきれいなうちに、花見に行きたい。']::text[], ARRAY['Trong lúc còn ở Nhật, tôi muốn đi thăm Kyoto một lần.','Tôi muốn đi ngắm hoa trong lúc hoa còn đẹp.']::text[]);
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('0b4b8464-a058-5549-b080-6159eb9c051c', 1, 'Trong khoảng thời gian đó, một việc ngoài dự tính đã xảy ra.', ARRAY['寒かったが、走っているうちに体が暖かくなった。','しばらく合わないうちに、日本語が上手になりましたね。']::text[], ARRAY['Trời lạnh, nhưng trong lúc đang chạy thì cơ thể đã ấm lên.','Chỉ trong thời gian ngắn không gặp mà tiếng Nhật của anh đã giỏi hẳn lên rồi nhỉ.']::text[]);

-- 21. ~おかげで/~おかげだ
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('6dcbe538-f87a-5430-840f-02ab7852f884', 0, 'Nhờ có, nhờ vào (nguyên nhân dẫn đến kết quả tốt, mang sắc thái biết ơn).', ARRAY['科学技術が発達したおかげで、我々の生活は便利になった。','仕事が早く済んだのは、山田さんのおかげです。']::text[], ARRAY['Nhờ khoa học kỹ thuật phát triển, cuộc sống của chúng ta trở nên tiện lợi hơn.','Công việc xong sớm là nhờ có anh Yamada.']::text[]);

-- 22. ~かわりに
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('adaa166d-4593-5550-89f4-c56c6a99588d', 0, 'Không làm việc này mà làm việc khác thay thế (thay vì).', ARRAY['私立大学を一つ受けるかわりに、国立大学を三つ受けたい。','音楽会に行くかわりに、CDを3枚買うほうがいいと思う。']::text[], ARRAY['Thay vì đăng ký thi một trường đại học tư, tôi muốn thi ba trường công lập.','Thay vì đi nghe hoà nhạc, tôi nghĩ mua ba đĩa CD sẽ tốt hơn.']::text[]);
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('adaa166d-4593-5550-89f4-c56c6a99588d', 1, 'Làm thay, đại diện cho người khác.', ARRAY['病気の父のかわりに、私が参りました。','包帯のかわりに、ハンカチで傷口を縛った。']::text[], ARRAY['Tôi đã đến thay cho bố đang bị ốm.','Thay vì dùng băng gạc, tôi đã dùng khăn tay để băng vết thương.']::text[]);
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('adaa166d-4593-5550-89f4-c56c6a99588d', 2, 'Bù lại, đổi lại (có mặt tốt thì kèm mặt tương xứng ngược lại).', ARRAY['私が料理するかわりに、あなたは掃除してください。','この部屋は狭いかわりに、家賃が安い。']::text[], ARRAY['Tôi nấu ăn, bù lại anh hãy dọn dẹp nhà cửa.','Căn phòng này tuy nhỏ nhưng bù lại tiền thuê rẻ.']::text[]);

-- 23. ~くらい/~ぐらい/~くらいだ/~ぐらいだ
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('11d8b93c-d18f-5ebe-ba5f-8265ea914125', 0, 'Biểu thị mức độ của trạng thái (đến mức mà...).', ARRAY['棚から物が落ちるくらい大きい地震があった。','おなかが痛くて、がまんできないぐらいだった。']::text[], ARRAY['Đã có một trận động đất lớn đến mức đồ vật rơi khỏi kệ.','Bụng đau đến mức không thể chịu đựng nổi.']::text[]);
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('11d8b93c-d18f-5ebe-ba5f-8265ea914125', 1, 'Biểu thị mức độ nhẹ, tối thiểu, không đòi hỏi nhiều.', ARRAY['忙しくても電話を掛けるくらいはできたでしょう。','人に会ったら、あいさつぐらいしてほしい。']::text[], ARRAY['Dù bận đến mấy thì ít nhất cũng gọi được một cuộc điện thoại chứ.','Khi gặp người khác, tôi mong anh ít nhất cũng chào hỏi.']::text[]);

-- 24. ~最中に/~最中だ
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('adba2ced-32cf-54ce-9253-63a6d0c53582', 0, 'Đúng vào lúc đang làm gì đó (bị việc khác xen vào giữa chừng).', ARRAY['考えている最中に、話しかけられて困った。','試合の最中に、雨が降ってきた。']::text[], ARRAY['Đang lúc suy nghĩ thì bị bắt chuyện, thật phiền.','Giữa trận đấu thì trời đổ mưa.']::text[]);

-- 25. ~次第
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('b0de3c0d-9b20-52b2-926c-e509a4e2cdff', 0, 'Ngay sau khi việc gì đó vừa kết thúc/xác định thì làm ngay việc tiếp theo.', ARRAY['新しい住所が決まり次第、連絡します。','向こうに着き次第、電話をしてください。']::text[], ARRAY['Ngay khi địa chỉ mới được xác định, tôi sẽ liên lạc.','Ngay khi đến nơi, hãy gọi điện cho tôi nhé.']::text[]);

-- 26. ~せいだ/~せいで/~せいか
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('83440e36-c0e8-5348-ae59-ac6c1b5fb8d9', 0, 'Tại vì, do (nguyên nhân dẫn đến kết quả không tốt, mang sắc thái đổ lỗi).', ARRAY['私が失敗したのは、彼のせいだ。','電車が遅れたせいで、遅刻した。']::text[], ARRAY['Tôi thất bại là tại anh ta.','Vì tàu điện bị trễ nên tôi đã đến muộn.']::text[]);

-- 27. ~たとたん（に）
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('de24af09-ce78-51e3-9cd9-12a84e2d15c3', 0, 'Ngay sau khi, vừa mới... thì (sự việc xảy ra bất ngờ ngay sau đó).', ARRAY['犯人は警官の姿を見たとたん、逃げ出した。','疲れていたので、ベッドに入ったとたんに、眠ってしまった。']::text[], ARRAY['Vừa thấy bóng cảnh sát, tên tội phạm đã bỏ chạy.','Vì mệt nên vừa nằm lên giường là đã ngủ mất ngay.']::text[]);

-- 28. ~たび（に）
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('fecf43ad-1cd9-56c3-84b1-50d6991ed506', 0, 'Mỗi khi, mỗi lần, mỗi dịp (lặp lại nhiều lần).', ARRAY['その歌を歌うたび、幼い日のことを思い出す。','私は旅行のたびに、絵葉書を買います。']::text[], ARRAY['Mỗi lần hát bài hát đó, tôi lại nhớ về những ngày thơ ấu.','Mỗi lần đi du lịch, tôi đều mua bưu thiếp.']::text[]);

-- 29. ~て以来
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('0f965e51-bdba-5f79-92b8-086e2979c5b8', 0, 'Từ khi... đến nay, kể từ khi (một trạng thái/việc gì tiếp diễn liên tục từ một mốc trong quá khứ đến hiện tại).', ARRAY['日本に来て以来、日本に対する考え方が少しずつ変わってきた。','昨年夏に手紙を受け取って以来、彼から連絡がまったくない。']::text[], ARRAY['Từ khi đến Nhật, cách nghĩ của tôi về Nhật Bản đã dần thay đổi.','Từ khi nhận được lá thư mùa hè năm ngoái, tôi hoàn toàn không có liên lạc gì từ anh ấy.']::text[]);

-- 30. ~とおり（に）/~どおり（に）
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('422637ac-2be5-57e6-bf68-cb2483b22929', 0, 'Giống hệt, đúng như (điều đã nói, đã viết, đã nghĩ, hoặc kế hoạch).', ARRAY['説明書に書いてあるとおりにやってみてください。','予想どおり、Aチームが優勝した。']::text[], ARRAY['Hãy thử làm đúng như những gì được viết trong bản hướng dẫn.','Đúng như dự đoán, đội A đã vô địch.']::text[]);

-- 31. ~ところに/~ところへ/~ところを
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('02785054-b90e-57c4-823d-7c37ddb975b4', 0, 'Đúng vào lúc, đúng địa điểm, đúng hoàn cảnh đó thì có việc khác xảy ra/xen vào.', ARRAY['ちょうど金さんのうわさをしているところに、本人がやって来た。','こっそりタバコを吸っているところを、妹に見られた。']::text[], ARRAY['Đúng lúc đang nói về anh Kim thì chính anh ấy xuất hiện.','Đang lén hút thuốc thì bị em gái bắt gặp.']::text[]);

-- 32. ~ほど/~ほどだ/~ほどの
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('dcc89bc9-11ac-559d-9700-deb776657468', 0, 'Biểu thị mức độ (đến chừng, đến mức...).', ARRAY['会場にはあふれるほど、ギターを持った若者が集まっていた。','子供をなくしたご両親の悲しみが痛いほど分かる。']::text[], ARRAY['Các thanh niên mang đàn ghi ta đã tụ tập đông đến mức tràn ngập cả hội trường.','Tôi hiểu được nỗi đau của những bậc cha mẹ mất con đến mức đau lòng.']::text[]);
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('dcc89bc9-11ac-559d-9700-deb776657468', 1, 'Nhấn mạnh cái gì đó là NHẤT, dùng ở dạng ~ほど…はない (không có gì... bằng).', ARRAY['仲のいい友達と旅行するほど楽しいことはない。','戦争ほど悲惨なものはない。']::text[], ARRAY['Không có gì vui bằng đi du lịch cùng bạn thân.','Không có gì bi thảm bằng chiến tranh.']::text[]);

-- 33. ~ばかりに
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('074c29ad-b1a7-5397-a22c-e803f8bf57c9', 0, 'Chỉ vì (một nguyên nhân nhỏ nhưng dẫn đến hậu quả đáng tiếc, nặng nề).', ARRAY['うそをついたばかりに恋人に嫌われてしまった。','日本語が下手なばかりに、いいアルバイトが探せません。']::text[], ARRAY['Chỉ vì nói dối mà tôi bị người yêu ghét bỏ.','Chỉ vì kém tiếng Nhật mà tôi không tìm được việc làm thêm tốt.']::text[]);

-- 34. ~ものだから
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('d13193ab-9376-5d91-99eb-1d128c2ad1b8', 0, 'Tại vì, là do (dùng khi giải thích, biện minh lý do cho một việc đã xảy ra).', ARRAY['事故で電車が遅れたものですから、遅くなってすみません。','日本の習慣を知らないものですから、失礼なことをするかもしれません。']::text[], ARRAY['Vì tàu điện bị trễ do tai nạn nên tôi xin lỗi vì đã đến muộn.','Vì không biết phong tục của Nhật nên có thể tôi sẽ làm điều gì đó thất lễ.']::text[]);

-- ============ grammar_points enrichment (memory_tip / comparison_note / common_mistake) ============

update grammar_points set memory_tip = 'として luôn đứng sau danh từ chỉ vai trò/chức danh, dịch nhanh là với tư cách là...', comparison_note = 'Dễ nhầm với ~にとって (nêu góc nhìn để đánh giá, phía sau thường là nhận xét/cảm nghĩ) - còn として nêu chính vai trò/tư cách của chủ thể khi hành động.', common_mistake = 'Người học hay dùng として khi thực ra muốn nói theo quan điểm của ai đó (phải dùng にとって), ví dụ nói sai 私としてこの映画はつまらない thay vì 私にとって.' where id = '1921b09f-1fbf-5365-93a8-19df0f52dc2a';
update grammar_points set memory_tip = 'とともに có 3 cách dùng: đi cùng ai (danh từ), làm 2 việc song song (thể từ điển/である), và 2 sự thay đổi cùng xảy ra - dựa vào từ loại đứng trước để phân biệt.', comparison_note = 'Dễ lẫn với ~につれて/~にしたがって (nghĩa thay đổi song song) - nhưng につれて/にしたがって chỉ dùng khi thay đổi diễn ra DẦN DẦN theo tỷ lệ, còn とともに chỉ đơn thuần nói hai việc xảy ra cùng lúc, không nhấn mạnh mức độ tăng dần.', common_mistake = 'Dùng とともに với nghĩa cùng ai đó rồi chia động từ ở thể である phía sau một cách máy móc - thực ra nghĩa này chỉ cần danh từ + とともに, không cần である.' where id = 'b52c5fac-a86e-557a-9a97-6e18a027bc8d';
update grammar_points set memory_tip = 'において = で trang trọng, thường dùng trong văn viết, phát biểu, báo cáo; dạng bổ nghĩa danh từ là における.', comparison_note = 'Dễ nhầm với ~について (nêu nội dung đang nói/suy nghĩ tới) - において chỉ nơi chốn/thời gian diễn ra sự việc, không phải nội dung đề cập.', common_mistake = 'Dùng において trong văn nói thân mật hàng ngày (nghe rất trang trọng, không tự nhiên) - nên dùng で cho hội thoại đời thường.' where id = '9bb0d0f6-5878-51c2-a134-6e7efa2374b1';
update grammar_points set memory_tip = 'に応じて luôn mang ý cân xứng, thay đổi theo tỷ lệ hợp lý với điều kiện đi trước.', comparison_note = 'Dễ nhầm với ~によって (nghĩa: tuỳ theo mà khác nhau) - によって chỉ đơn thuần nêu có sự khác nhau tuỳ trường hợp, còn に応じて nhấn mạnh sự PHÙ HỢP, CÂN XỨNG có chủ đích.', common_mistake = 'Dùng に応じて khi chỉ muốn nói sự khác biệt chung chung không có tính tương xứng (nên dùng によって), ví dụ 習慣は国に応じて違う nghe không tự nhiên bằng 習慣は国によって違う.' where id = '983b21b1-3f11-5cdb-aaac-1449ab9892b2';
update grammar_points set memory_tip = 'にかわって luôn có nghĩa THAY THẾ hẳn (đổi chỗ), khác với かわりに vốn linh hoạt hơn (có cả nghĩa bù trừ, đổi việc).', comparison_note = 'Dễ nhầm với ~のかわりに - にかわって trang trọng, thường dùng cho việc thay thế chính thức (đại diện phát biểu, thay thế công nghệ), còn のかわりに thông dụng hơn và có thêm nghĩa bù lại, tương xứng mà にかわって không có.', common_mistake = 'Dùng にかわって cho các việc nhỏ nhặt đời thường (như ăn cơm thay vì ăn phở) - trường hợp này nên dùng のかわりに vì にかわって nghe quá trang trọng.' where id = '7a5bdce1-c437-59d1-9d9b-46ef8dc7916b';
update grammar_points set memory_tip = 'に比べて luôn cần 2 đối tượng để so sánh - vế trước に比べて là chuẩn so sánh, vế sau là nhận xét khác biệt.', comparison_note = 'Dễ nhầm với ~によって (nghĩa: tuỳ theo mà khác nhau) - に比べて là so sánh trực tiếp GIỮA HAI đối tượng cụ thể, còn によって chỉ nói có sự khác nhau tuỳ trường hợp, không so sánh 1-1.', common_mistake = 'Quên trợ từ に trước 比べて (viết nhầm thành 兄を比べて) - đúng phải là 兄に比べて.' where id = '960445c3-aa9b-57e2-9948-bb88b409af8f';
update grammar_points set memory_tip = 'にしたがって thường đi với động từ chỉ sự biến đổi dần dần (増える、減る、高くなる...), diễn tả quan hệ tỷ lệ thuận.', comparison_note = 'Gần như đồng nghĩa với ~につれて, nhưng にしたがって còn có thể dùng với nghĩa tuân theo quy tắc, chỉ dẫn, trong khi につれて chỉ dùng cho nghĩa thay đổi song song.', common_mistake = 'Dùng にしたがって với 2 sự việc không liên quan nhân quả rõ ràng (phải là quan hệ biến đổi tỷ lệ thuận thật sự, không phải chỉ xảy ra cùng lúc).' where id = '491bbfa2-cf02-582f-94d1-d9b80014d682';
update grammar_points set memory_tip = 'につれて gần như luôn thay thế được bằng にしたがって trong nghĩa thay đổi song song, nhưng につれて không dùng được cho nghĩa tuân theo mệnh lệnh, chỉ dẫn.', comparison_note = 'So với ~に伴って - につれて chỉ dùng cho quá trình biến đổi DẦN DẦN, còn に伴って dùng được cả cho sự kiện xảy ra ĐỒNG THỜI (không nhất thiết tăng/giảm từ từ).', common_mistake = 'Dùng につれて cho một sự kiện xảy ra đột ngột, tức thời (không phải quá trình dần dần) - trường hợp đó nên dùng とたんに hoặc に伴って.' where id = '2b817f7e-e626-547d-9bb6-4baae56d3dc5';
update grammar_points set memory_tip = 'に対して luôn trả lời câu hỏi hướng tới ai/cái gì, dạng bổ nghĩa danh từ là に対する.', comparison_note = 'Dễ nhầm với ~について - に対して chỉ ĐỐI TƯỢNG của thái độ/hành động (thường có sắc thái tương tác qua lại), còn について chỉ NỘI DUNG đang nói/nghĩ tới.', common_mistake = 'Dùng について khi thực ra muốn nói thái độ hướng đến ai đó, ví dụ nói sai 彼について怒っている thay vì đúng phải là 彼に対して怒っている.' where id = 'd77a1e12-f7d4-5ac2-8d62-de3e71d9312d';
update grammar_points set memory_tip = 'について luôn theo sau bởi động từ nói/nghĩ/nghiên cứu (話す、考える、研究する...), dạng bổ nghĩa danh từ là についての.', comparison_note = 'Xem thêm so sánh với ~に対して - について là nội dung đề cập, に対して là đối tượng chịu tác động/thái độ.', common_mistake = 'Dùng について để chỉ đối tượng của thái độ (giận, yêu, ghét...) thay vì に対して - đây là lỗi hay gặp vì cả hai đều dịch là về, đối với.' where id = '2cf50cce-fb26-520c-a819-aed92216a848';
update grammar_points set memory_tip = 'にとって luôn đi kèm câu đánh giá/nhận xét ở vế sau (quan trọng, khó, tốt, xấu...), không dùng cho hành động cụ thể.', comparison_note = 'Xem thêm so sánh với ~として - にとって là góc nhìn để đánh giá, として là tư cách/vai trò khi hành động.', common_mistake = 'Dùng にとって rồi chia động từ hành động cụ thể ở vế sau (như làm gì đó) - にとって chỉ hợp với câu nhận xét/đánh giá, không hợp với câu miêu tả hành động.' where id = '86cc8574-9590-5229-8ef0-1af4e4fc68a0';
update grammar_points set memory_tip = 'に伴って dùng được cả cho danh từ chỉ sự kiện lớn (地震、戦争、発展...), không chỉ cho động từ biến đổi dần dần.', comparison_note = 'So sánh với ~につれて/~にしたがって - に伴って phạm vi rộng hơn, dùng được cho cả sự kiện xảy ra tức thời cùng lúc, còn につれて/にしたがって chỉ hợp với quá trình biến đổi từ từ.', common_mistake = 'Dùng につれて cho một sự kiện đột ngột như 地震 (động đất) - trường hợp này phải dùng に伴って, không dùng につれて vì につれて cần yếu tố thay đổi dần dần.' where id = '7df4deaf-d5fc-5a27-8f02-26215b350a62';
update grammar_points set memory_tip = 'によって có tới 5 cách dùng (chủ thể bị động, nguyên nhân, phương thức, sự khác nhau tuỳ đối tượng, trường hợp cá biệt) - cần dựa vào ngữ cảnh câu để xác định đúng nghĩa.', comparison_note = 'Nghĩa tuỳ theo mà khác nhau dễ nhầm với ~に応じて - によって chỉ nêu có sự khác biệt, còn に応じて nhấn mạnh sự phù hợp, cân xứng có chủ đích.', common_mistake = 'Dùng nhầm によって (nguyên nhân) thay cho ので/から trong văn nói thông thường - によって mang tính trang trọng, ít dùng trong hội thoại hàng ngày.' where id = '721e6341-58cf-51ef-97ef-80504a084229';
update grammar_points set memory_tip = 'によると luôn kết thúc câu bằng ~そうだ/~ということだ (thể truyền đạt lại thông tin), không dùng để kết luận bằng ý kiến cá nhân.', comparison_note = 'Dễ nhầm với ~によって (nghĩa nguyên nhân) vì cùng gốc によって - によると chỉ dùng để dẫn NGUỒN TIN, không mang nghĩa nguyên nhân.', common_mistake = 'Dùng によると nhưng lại kết câu bằng ý kiến chủ quan của bản thân (phải kết bằng そうだ/ということだ để thể hiện đây là tin nghe được, không phải quan điểm riêng).' where id = '8cfd8bee-b151-5705-a88a-1012faef7b87';
update grammar_points set memory_tip = 'を中心に(して) hay を中心として đều dùng được, nghĩa như nhau, khác nhau về mức độ trang trọng (として trang trọng hơn).', comparison_note = 'Dễ nhầm với ~をもとに - を中心に nhấn mạnh vị trí/vai trò TRUNG TÂM (không gian, chủ đề), còn をもとに nhấn mạnh CĂN CỨ, CƠ SỞ để làm việc gì.', common_mistake = 'Dùng を中心に khi ý muốn nói dựa trên căn cứ nào đó (phải dùng をもとに), ví dụ nói sai データを中心に判断する thay vì データをもとに判断する.' where id = '5bdfa8a2-646b-5039-a65a-dd9f9a9853ee';
update grammar_points set memory_tip = 'を問わず thường đi sau danh từ chỉ phạm trù đối lập (男女、昼夜、国籍…) để nói phạm trù đó không ảnh hưởng.', comparison_note = 'Dễ nhầm với ~にかかわらず - を問わず thiên về liệt kê phạm vi rộng một cách trung tính, còn にかかわらず thường nhấn mạnh sắc thái dù có... hay không rõ hơn.', common_mistake = 'Dùng を問わず với một danh từ đơn lẻ không mang tính đối lập/phạm trù (を問わず cần danh từ kiểu cặp đối lập như 有無、男女, không dùng tuỳ tiện với danh từ bất kỳ).' where id = '76dd1cae-6d93-5532-b6ec-fb6962b5e348';
update grammar_points set memory_tip = 'をはじめ(とする) luôn nêu MỘT ví dụ tiêu biểu nhất rồi ngầm hiểu còn nhiều thứ khác cùng loại phía sau.', comparison_note = 'Dễ nhầm với ~を中心に - をはじめ chỉ đưa ra ví dụ điển hình mở đầu danh sách, còn を中心に nói về vai trò trung tâm, chủ đạo, không nhất thiết là liệt kê.', common_mistake = 'Dùng をはじめ mà không có phần liệt kê/nhóm phía sau (をはじめ luôn ngụ ý còn có những thứ khác cùng loại, nếu chỉ có một đối tượng duy nhất thì không dùng được).' where id = '1bf5b207-3099-59c4-bb34-0eb2c51a94f4';
update grammar_points set memory_tip = 'をもとに(して) = dựa trên, lấy làm căn cứ - vế sau luôn là hành động TẠO RA cái gì mới từ căn cứ đó (viết, quyết định, xây dựng...).', comparison_note = 'Xem thêm so sánh với ~を中心に - をもとに là căn cứ để tạo ra kết quả, còn を中心に là vai trò trung tâm.', common_mistake = 'Nhầm lẫn をもとに với に基づいて (nghĩa gần giống dựa trên) - をもとに thiên về dùng tài liệu/thông tin để sáng tạo ra cái mới, còn に基づいて trang trọng hơn, thường dùng cho quy định, luật lệ, số liệu chính thức.' where id = 'be4d2740-8b3b-5dcf-962d-868b11600255';
update grammar_points set memory_tip = '~上（に） luôn nối 2 điều có cùng chiều hướng tốt-tốt hoặc xấu-xấu, không dùng để nối 2 điều trái ngược nhau.', comparison_note = 'Dễ nhầm với ~に加えて (nghĩa gần giống thêm vào đó) - 上に thiên về diễn tả 2 tính chất/trạng thái liên quan tự nhiên xảy ra cùng nhau, còn に加えて mang tính liệt kê thêm một yếu tố độc lập hơn.', common_mistake = 'Dùng ~上（に）để nối 2 vế trái chiều nhau (một tốt một xấu) - trường hợp đó phải dùng ~のに hoặc ~が, không dùng 上に.' where id = '04ad6c89-1aec-5959-bc3a-0f91f9ba351c';
update grammar_points set memory_tip = 'うちに (nghĩa A) mang ý CHỦ ĐỘNG tranh thủ làm gì trước khi hết thời gian, còn うちに (nghĩa B) mang ý BỊ ĐỘNG, việc tự xảy ra ngoài ý muốn trong khoảng thời gian đó.', comparison_note = 'Dễ nhầm với ~最中に - うちに nhấn mạnh khoảng THỜI GIAN còn kéo dài để tranh thủ làm việc khác, còn 最中に nhấn mạnh đúng THỜI ĐIỂM đang xảy ra và bị việc khác xen vào.', common_mistake = 'Dùng うちに với động từ chỉ hành động có chủ đích ở nghĩa B (nghĩa B chỉ đi với hiện tượng tự nhiên xảy ra, không phải hành động có chủ đích của người nói).' where id = '0b4b8464-a058-5549-b080-6159eb9c051c';
update grammar_points set memory_tip = 'おかげで luôn đi với kết quả TỐT và mang sắc thái biết ơn - nhớ nhanh bằng cách liên tưởng nhờ ơn.', comparison_note = 'Trái nghĩa với ~せいで - おかげで dùng cho kết quả tốt, せいで dùng cho kết quả xấu, đổ lỗi.', common_mistake = 'Dùng おかげで cho kết quả xấu để mỉa mai (thực tế người Việt hay nói kiểu nhờ có anh mà tôi trễ giờ theo nghĩa châm biếm, nhưng trong tiếng Nhật おかげで luôn được hiểu nghĩa đen là biết ơn, nên tránh dùng mỉa mai).' where id = '6dcbe538-f87a-5430-840f-02ab7852f884';
update grammar_points set memory_tip = 'かわりに rất linh hoạt: thay việc này bằng việc khác, làm thay người khác, hoặc bù lại/đánh đổi - cần đọc kỹ ngữ cảnh 2 vế để chọn đúng nghĩa.', comparison_note = 'So sánh với ~にかわって - にかわって trang trọng và chỉ mang nghĩa gần giống 2 nghĩa đầu của かわりに, không có nghĩa bù lại, tương xứng.', common_mistake = 'Nhầm lẫn giữa 3 nghĩa của かわりに, đặc biệt hay bỏ sót nghĩa bù lại/đánh đổi và dịch sai thành thay vì trong khi câu thực chất đang so sánh 2 mặt tốt-xấu tương xứng.' where id = 'adaa166d-4593-5550-89f4-c56c6a99588d';
update grammar_points set memory_tip = 'くらい (nghĩa A) đứng sau mệnh đề miêu tả trạng thái để nhấn mạnh MỨC ĐỘ CAO, còn くらい (nghĩa B) đứng sau một hành động đơn giản để nói MỨC ĐỘ THẤP, tối thiểu.', comparison_note = 'Dễ nhầm với ~ほど - hai từ gần như thay thế được cho nhau ở nghĩa mức độ, nhưng ほど thường dùng trong cấu trúc so sánh nhất ~ほど…はない, còn くらい linh hoạt hơn và có thêm nghĩa mức độ tối thiểu mà ほど không có.', common_mistake = 'Dùng ぐらい/くらい ở nghĩa mức tối thiểu nhưng lại thay bằng ほど - ほど không mang được sắc thái chỉ cần chút ít cũng được như くらい.' where id = '11d8b93c-d18f-5ebe-ba5f-8265ea914125';
update grammar_points set memory_tip = '最中に luôn theo sau động từ ở thể ている hoặc danh từ + の, diễn tả một hành động ĐANG diễn ra dở dang.', comparison_note = 'Xem thêm so sánh với ~うちに - 最中に nhấn mạnh đúng thời điểm đang xảy ra và có sự việc khác xen vào, còn うちに nhấn mạnh khoảng thời gian còn kéo dài để tranh thủ làm việc khác.', common_mistake = 'Dùng 最中に với động từ ở thể từ điển thay vì thể ている (phải là 考えている最中に, không phải 考える最中に).' where id = 'adba2ced-32cf-54ce-9253-63a6d0c53582';
update grammar_points set memory_tip = '次第 luôn gắn sau động từ thể ます (bỏ ます), diễn tả hành động chủ động làm ngay sau khi điều kiện hoàn thành.', comparison_note = 'Dễ nhầm với ~たとたん（に）- 次第 mang tính chủ động, có kế hoạch (làm gì ngay sau khi xong việc), còn たとたんに diễn tả sự việc xảy ra bất ngờ, không có ý định của người nói.', common_mistake = 'Dùng 次第 với động từ ở thể quá khứ (phải dùng thể ます bỏ ます, ví dụ 決まり次第, không phải 決まった次第).' where id = 'b0de3c0d-9b20-52b2-926c-e509a4e2cdff';
update grammar_points set memory_tip = 'せいだ/せいで dùng cho kết quả XẤU, còn せいか thêm sắc thái không chắc chắn (có lẽ là do...).', comparison_note = 'Trái nghĩa với ~おかげで - おかげで dùng cho kết quả tốt (biết ơn), せいで dùng cho kết quả xấu (đổ lỗi).', common_mistake = 'Dùng せいで cho kết quả TỐT (đây là lỗi phổ biến vì せい nghe gần giống おかげ về mặt cấu trúc câu, nhưng ý nghĩa hoàn toàn trái ngược).' where id = '83440e36-c0e8-5348-ae59-ac6c1b5fb8d9';
update grammar_points set memory_tip = 'たとたん（に） luôn gắn sau động từ thể た (quá khứ), diễn tả sự việc xảy ra RẤT NHANH và BẤT NGỜ ngay sau đó.', comparison_note = 'Xem thêm so sánh với ~次第 - たとたんに diễn tả việc xảy ra bất ngờ, ngoài ý muốn, còn 次第 diễn tả hành động có chủ đích, làm ngay sau khi điều kiện hoàn thành.', common_mistake = 'Dùng たとたんに cho hành động có chủ đích, có kế hoạch từ trước (たとたんに chỉ hợp với sự việc bất ngờ, không định trước).' where id = 'de24af09-ce78-51e3-9cd9-12a84e2d15c3';
update grammar_points set memory_tip = 'たび（に） luôn mang nghĩa LẶP LẠI nhiều lần, khác với たとたんに chỉ nói về MỘT lần cụ thể.', comparison_note = 'Dễ nhầm với ~たとたん（に）- たび（に）diễn tả sự việc lặp lại đều đặn mỗi khi có điều kiện, còn たとたんに chỉ nói về một lần xảy ra bất ngờ, tức thời.', common_mistake = 'Dùng たび（に） cho một sự việc chỉ xảy ra đúng một lần (たび（に） bắt buộc phải có tính lặp lại, không dùng cho sự kiện đơn lẻ).' where id = 'fecf43ad-1cd9-56c3-84b1-50d6991ed506';
update grammar_points set memory_tip = 'て以来 luôn nói về việc TIẾP DIỄN LIÊN TỤC từ mốc thời gian đó đến hiện tại, không dùng cho việc chỉ xảy ra một lần rồi kết thúc.', comparison_note = 'Dễ nhầm với ~てから (chỉ đơn thuần sau khi làm gì) - て以来 nhấn mạnh tính LIÊN TỤC kéo dài đến hiện tại, còn てから chỉ nói về trình tự trước sau, không nhấn mạnh tính liên tục.', common_mistake = 'Dùng て以来 với vế sau là một hành động chỉ xảy ra một lần, không mang tính trạng thái kéo dài (て以来 cần vế sau diễn tả trạng thái/xu hướng tiếp diễn).' where id = '0f965e51-bdba-5f79-92b8-086e2979c5b8';
update grammar_points set memory_tip = '動詞/た形 + とおりに hoặc 名詞 + どおりに - nhớ quy tắc: danh từ thì dùng どおり (đục âm), động từ/mệnh đề thì dùng とおり.', comparison_note = 'Dễ nhầm với ~ように (nghĩa ví dụ) - とおりに khẳng định sự việc GIỐNG HỆT, chính xác, còn ように mang tính ước lệ, ví von, không cần chính xác tuyệt đối.', common_mistake = 'Dùng danh từ + とおり mà quên chuyển âm thành どおり (viết sai 計画とおり thay vì đúng phải là 計画どおり).' where id = '422637ac-2be5-57e6-bf68-cb2483b22929';
update grammar_points set memory_tip = 'ところに/ところへ/ところを luôn theo sau động từ thể ている hoặc た, diễn tả một khoảnh khắc cụ thể bị xen ngang bởi sự việc khác.', comparison_note = 'Xem thêm so sánh với ~最中に - ところに nhấn mạnh khoảnh khắc chính xác (thường có yếu tố bất ngờ/trùng hợp), còn 最中に nhấn mạnh trạng thái đang kéo dài.', common_mistake = 'Nhầm lẫn 3 trợ từ に/へ/を đi sau ところ - に/へ dùng khi vế sau là động từ đến/xuất hiện, còn を dùng khi vế sau là hành động bắt gặp, phát hiện (thường ở thể bị động như 見られた).' where id = '02785054-b90e-57c4-823d-7c37ddb975b4';
update grammar_points set memory_tip = 'ほど (nghĩa B) luôn xuất hiện trong khuôn ~ほど…はない để nói cái được nêu ra là NHẤT, không cần so sánh trực tiếp với đối tượng khác.', comparison_note = 'Xem thêm so sánh với ~くらい/~ぐらい - ほど thiên về cấu trúc so sánh nhất, còn くらい linh hoạt hơn và có thêm nghĩa mức độ tối thiểu.', common_mistake = 'Dùng ほど (nghĩa B) nhưng quên phủ định はない ở cuối câu - cấu trúc bắt buộc phải có はない thì mới mang nghĩa nhất, thiếu phủ định sẽ đổi nghĩa.' where id = 'dcc89bc9-11ac-559d-9700-deb776657468';
update grammar_points set memory_tip = 'ばかりに luôn đi kèm sắc thái TIẾC NUỐI, hối hận về hậu quả nặng nề so với nguyên nhân nhỏ nhặt.', comparison_note = 'Xem thêm so sánh với ~せいで - ばかりに mang sắc thái tiếc nuối, hối hận mạnh hơn せいで, và thường dùng khi nguyên nhân chỉ là một điều nhỏ nhặt so với hậu quả nghiêm trọng.', common_mistake = 'Dùng ばかりに cho kết quả TỐT hoặc trung tính - ばかりに bắt buộc phải đi với hậu quả TIÊU CỰC, đáng tiếc.' where id = '074c29ad-b1a7-5397-a22c-e803f8bf57c9';
update grammar_points set memory_tip = 'ものだから thường dùng trong văn nói, mang sắc thái GIẢI THÍCH/XIN LỖI cho một việc đã lỡ xảy ra, không dùng để nêu lý do khách quan trung tính.', comparison_note = 'Xem thêm so sánh với ~ばかりに - ものだから thiên về giải thích, biện minh nhẹ nhàng (dùng khi xin lỗi), còn ばかりに nhấn mạnh hậu quả đáng tiếc, nghiêm trọng hơn nhiều.', common_mistake = 'Dùng ものだから trong văn viết trang trọng, báo cáo chính thức (ものだから mang tính khẩu ngữ, nên dùng ため hoặc から trong văn viết trang trọng).' where id = 'd13193ab-9376-5d91-99eb-1d128c2ad1b8';
